// WPF returned Visibility; Avalonia visibility is a bool (IsVisible), so this is
// bool -> inverted bool in the Avalonia dialect ([ValueConversion] has no analog).
// @port: Daqifi.Desktop.Converters.InvertedBoolToVisibilityConverter
public class InvertedBoolToVisibilityConverter : IValueConverter
{
    // @port: Daqifi.Desktop.Converters.InvertedBoolToVisibilityConverter.Convert
    public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
    {
        if (value is bool booleanValue)
